-- Phase P5 pgTAP (docs/RMS_PHASE_PROMPTS_20-11-2026.md, DEC-65; migration 20261121000100):
-- transfer slips are generated by the RM only, backed by a custody transfer from Inward Staging to
-- the slip's store (G-09), carry each line on one live slip of its product's store, match the split
-- (G-19), are append-only, and a GS reaches TRANSFER_SLIP_GENERATED only fully covered. Edit
-- requests block generation; only Management voids a slip; post-lock edits need the slips voided.
begin;
create extension if not exists pgtap with schema extensions;
select plan(21);

insert into auth.users (id, email, raw_app_meta_data, raw_user_meta_data) values
  ('aaaaaaaa-0000-4000-8000-0000000005e1', 'pgtap-p5-re@example.test', '{"rms_activate": true}', '{"full_name": "P5 RE"}'),
  ('aaaaaaaa-0000-4000-8000-0000000005e2', 'pgtap-p5-rm@example.test', '{"rms_activate": true}', '{"full_name": "P5 RM"}'),
  ('aaaaaaaa-0000-4000-8000-0000000005e3', 'pgtap-p5-mgmt@example.test', '{"rms_activate": true}', '{"full_name": "P5 Mgmt"}');
insert into public.user_roles (user_id, role_id)
select 'aaaaaaaa-0000-4000-8000-0000000005e1'::uuid, id from public.roles where code = 'INWARD_VERIFIER'
union all
select 'aaaaaaaa-0000-4000-8000-0000000005e2'::uuid, id from public.roles where code = 'REPLACEMENT_MANAGER'
union all
select 'aaaaaaaa-0000-4000-8000-0000000005e3'::uuid, id from public.roles where code = 'MANAGEMENT';

create temp table _p5 as
select v.id as wv,
       (select p.id from public.products p
          join public.product_categories c on c.id = p.category_id and c.code = 'DMT'
         where exists (select 1 from rms_private.resolve_item_field_profile(p.id) r
                        where r.field_group = 'CATEGORISATION') limit 1) as product,
       (select id from public.intermediate_stores where code = 'DT') as dt,
       (select id from public.intermediate_stores where code = 'OP') as op,
       (select location_id from public.intermediate_stores where code = 'DT') as dt_loc,
       (select location_id from public.intermediate_stores where code = 'OP') as op_loc,
       (select id from public.inventory_locations where code = 'INWARD_STAGING') as staging
  from public.workflow_versions v
  join public.workflow_definitions d on d.id = v.workflow_definition_id and d.code = 'RMS_STANDARD'
 where v.status = 'PUBLISHED';

-- Two locked Replacement GSs, one DMT line of 4 each, split into one bucket.
insert into public.goods_slips (gs_no, workflow_version_id, delivery_mode_code, courier_name, docket_no,
                                carton_count, status, category_code, original_category_code)
select g, wv, 'COURIER_PARCEL', 'A', g, 1, 'CATEGORISATION', 'RO', 'RO'
  from _p5, (values ('PGTAP-P5-A'), ('PGTAP-P5-B')) as v(g);
insert into public.gs_items (gs_id, line_no, product_id, category_id, documented_qty, received_qty)
select g.id, 1, p.id, p.category_id, 4, 4
  from public.goods_slips g, _p5 join public.products p on p.id = _p5.product
 where g.gs_no like 'PGTAP-P5-%';
insert into public.gs_item_buckets (gs_item_id, field_id, qty)
select i.id, (select r.field_id from rms_private.resolve_item_field_profile(i.product_id) r
               where r.field_group = 'CATEGORISATION' limit 1), 4
  from public.gs_items i join public.goods_slips g on g.id = i.gs_id where g.gs_no like 'PGTAP-P5-%';
update public.goods_slips set status = 'PENDING_TRANSFER_SLIP', categorisation_locked_at = now(),
       categorisation_locked_by = 'aaaaaaaa-0000-4000-8000-0000000005e1'
 where gs_no like 'PGTAP-P5-%';

create temp table _ids as
select (select id from public.goods_slips where gs_no = 'PGTAP-P5-A') as gs_a,
       (select id from public.goods_slips where gs_no = 'PGTAP-P5-B') as gs_b,
       (select i.id from public.gs_items i join public.goods_slips g on g.id = i.gs_id where g.gs_no = 'PGTAP-P5-A') as item_a,
       (select b.field_id from public.gs_item_buckets b join public.gs_items i on i.id = b.gs_item_id
          join public.goods_slips g on g.id = i.gs_id where g.gs_no = 'PGTAP-P5-A') as field_a;

-- Custody transfers behind the slips (setup; the engine itself is covered by the P3-01 tests).
select set_config('app.user_id', 'aaaaaaaa-0000-4000-8000-0000000005e2', true);
insert into public.custody_transfers (transfer_no, from_location_id, to_location_id, status)
select 'PGTAP-P5-CT-DT', staging, dt_loc, 'INITIATED' from _p5
union all select 'PGTAP-P5-CT-OP', staging, op_loc, 'INITIATED' from _p5
union all select 'PGTAP-P5-CT-DT2', staging, dt_loc, 'INITIATED' from _p5;

-- 1. Only the RM (transfer_slips.create) generates.
select set_config('app.user_id', 'aaaaaaaa-0000-4000-8000-0000000005e1', true);
select throws_like(
  $$insert into public.transfer_slips (slip_no, store_id, store_code_snapshot, store_name_snapshot,
       custody_transfer_id, relevant_qty, grand_total_qty, template_version_no)
    select 'PGTAP-TRF-X', dt, '', '', (select id from public.custody_transfers where transfer_no = 'PGTAP-P5-CT-DT'),
           4, 4, 1 from _p5$$,
  'DEC-65:%Replacement Manager%', 'DEC-65: the Replacement Executive cannot generate a slip');

-- 2. G-09: the custody transfer must go from Inward Staging to the slip's store.
select set_config('app.user_id', 'aaaaaaaa-0000-4000-8000-0000000005e2', true);
select throws_like(
  $$insert into public.transfer_slips (slip_no, store_id, store_code_snapshot, store_name_snapshot,
       custody_transfer_id, relevant_qty, grand_total_qty, template_version_no)
    select 'PGTAP-TRF-X', dt, '', '', (select id from public.custody_transfers where transfer_no = 'PGTAP-P5-CT-OP'),
           4, 4, 1 from _p5$$,
  'G-09:%', 'G-09: a DT slip cannot ride on a transfer to OP');

select lives_ok(
  $$insert into public.transfer_slips (slip_no, store_id, store_code_snapshot, store_name_snapshot,
       custody_transfer_id, relevant_qty, grand_total_qty, template_version_no)
    select 'PGTAP-TRF-DT', dt, '', '', (select id from public.custody_transfers where transfer_no = 'PGTAP-P5-CT-DT'),
           4, 4, 1 from _p5
    union all
    select 'PGTAP-TRF-OP', op, '', '', (select id from public.custody_transfers where transfer_no = 'PGTAP-P5-CT-OP'),
           4, 4, 1 from _p5$$,
  'DEC-65: the RM generates slips backed by their custody transfers');
select is((select store_code_snapshot from public.transfer_slips where slip_no = 'PGTAP-TRF-DT'), 'DT',
  'G-18: the store snapshot is taken by the database');

select lives_ok(
  $$insert into public.transfer_slip_gs (slip_id, gs_id, gs_no_snapshot, relevant_qty, total_qty)
    select s.id, i.gs_a, '', 4, 4 from public.transfer_slips s, _ids i where s.slip_no in ('PGTAP-TRF-DT', 'PGTAP-TRF-OP')$$,
  'DEC-65: GS A goes on the slips');

-- 3. Lines: the split (G-19), the product's store, one live slip per line.
select throws_like(
  $$insert into public.transfer_slip_lines (slip_id, gs_id, gs_item_id, line_no_snapshot, product_id,
       product_name_snapshot, bucket_field_id, qty, is_relevant, belongs_store_id, belongs_store_name_snapshot)
    select s.id, i.gs_a, i.item_a, 1, p.product, 'X', i.field_a, 3, true, p.dt, 'DT'
      from public.transfer_slips s, _ids i, _p5 p where s.slip_no = 'PGTAP-TRF-DT'$$,
  'G-19:%', 'G-19: the slip qty must equal the condition split');
select throws_like(
  $$insert into public.transfer_slip_lines (slip_id, gs_id, gs_item_id, line_no_snapshot, product_id,
       product_name_snapshot, bucket_field_id, qty, is_relevant, belongs_store_id, belongs_store_name_snapshot)
    select s.id, i.gs_a, i.item_a, 1, p.product, 'X', i.field_a, 4, true, p.op, 'OP'
      from public.transfer_slips s, _ids i, _p5 p where s.slip_no = 'PGTAP-TRF-OP'$$,
  'DEC-65:%another Intermediate Store%', 'DEC-61/65: a DMT line is not relevant on the OP slip');
select lives_ok(
  $$insert into public.transfer_slip_lines (slip_id, gs_id, gs_item_id, line_no_snapshot, product_id,
       product_name_snapshot, bucket_field_id, qty, is_relevant, belongs_store_id, belongs_store_name_snapshot)
    select s.id, i.gs_a, i.item_a, 1, p.product, 'X', i.field_a, 4, true, p.dt, 'DT'
      from public.transfer_slips s, _ids i, _p5 p where s.slip_no = 'PGTAP-TRF-DT'$$,
  'DEC-65: the DMT line goes on the DT slip');

-- A second DT slip cannot carry the same line while the first is live.
insert into public.transfer_slips (slip_no, store_id, store_code_snapshot, store_name_snapshot,
       custody_transfer_id, relevant_qty, grand_total_qty, template_version_no)
select 'PGTAP-TRF-DT2', dt, '', '', (select id from public.custody_transfers where transfer_no = 'PGTAP-P5-CT-DT2'),
       4, 4, 1 from _p5;
insert into public.transfer_slip_gs (slip_id, gs_id, gs_no_snapshot, relevant_qty, total_qty)
select s.id, i.gs_a, '', 4, 4 from public.transfer_slips s, _ids i where s.slip_no = 'PGTAP-TRF-DT2';
select throws_like(
  $$insert into public.transfer_slip_lines (slip_id, gs_id, gs_item_id, line_no_snapshot, product_id,
       product_name_snapshot, bucket_field_id, qty, is_relevant, belongs_store_id, belongs_store_name_snapshot)
    select s.id, i.gs_a, i.item_a, 1, p.product, 'X', i.field_a, 4, true, p.dt, 'DT'
      from public.transfer_slips s, _ids i, _p5 p where s.slip_no = 'PGTAP-TRF-DT2'$$,
  'DEC-65:%already on a live transfer slip%', 'DEC-65: a line is on one live slip only');

-- 4. Status chain: covered → TRANSFER_SLIP_GENERATED; uncovered GS B refused.
select lives_ok(
  $$update public.goods_slips set status = 'TRANSFER_SLIP_GENERATED' where gs_no = 'PGTAP-P5-A'$$,
  'DEC-65: a fully covered GS reaches TRANSFER_SLIP_GENERATED');
select throws_like(
  $$update public.goods_slips set status = 'TRANSFER_SLIP_GENERATED' where gs_no = 'PGTAP-P5-B'$$,
  'DEC-65:%every physical line%', 'DEC-65: an uncovered GS cannot leave PENDING_TRANSFER_SLIP');

-- 5. Append-only.
select throws_like(
  $$update public.transfer_slip_lines set qty = 5 where slip_id = (select id from public.transfer_slips where slip_no = 'PGTAP-TRF-DT')$$,
  'DEC-65:%immutable%', 'DEC-65: slip lines are immutable');
select throws_like(
  $$update public.transfer_slips set relevant_qty = 9 where slip_no = 'PGTAP-TRF-DT'$$,
  'DEC-65:%only its status changes%', 'DEC-65: a slip only changes status');
select throws_like(
  $$delete from public.transfer_slips where slip_no = 'PGTAP-TRF-DT'$$,
  'DEC-65:%never deleted%', 'DEC-65: slips are never deleted');

-- 6. Edit requests: OPEN keeps GS B off the slips; only Management resolves.
select lives_ok(
  $$insert into public.gs_edit_requests (gs_id, reason) select gs_b, 'wrong qty' from _ids$$,
  'DEC-65: the RM sends an edit request');
select throws_like(
  $$insert into public.transfer_slip_gs (slip_id, gs_id, gs_no_snapshot, relevant_qty, total_qty)
    select s.id, i.gs_b, '', 4, 4 from public.transfer_slips s, _ids i where s.slip_no = 'PGTAP-TRF-DT2'$$,
  'DEC-65:%open edit request%', 'DEC-65: a GS with an open edit request cannot go on a slip');
select throws_like(
  $$update public.gs_edit_requests set status = 'REJECTED', resolved_at = now(),
           resolved_by = 'aaaaaaaa-0000-4000-8000-0000000005e2', resolution_note = 'no'
     where gs_id = (select gs_b from _ids)$$,
  'DEC-65:%Super Admin or Management%', 'DEC-65: the RM cannot resolve its own request');

-- 7. Q10: only Management voids; post-lock edits need the live slips voided first.
select throws_like(
  $$update public.transfer_slips set status = 'VOIDED', voided_at = now(),
           voided_by = 'aaaaaaaa-0000-4000-8000-0000000005e2', void_reason = 'test'
     where slip_no = 'PGTAP-TRF-DT'$$,
  'DEC-65:%Super Admin or Management%', 'DEC-65 / Q10: the RM cannot void a slip');
select set_config('app.user_id', 'aaaaaaaa-0000-4000-8000-0000000005e3', true);
select throws_like(
  $$select rms_private.assert_locked_gs_edit((select gs_a from _ids))$$,
  'DEC-65:%void the live transfer slips%', 'DEC-65 / Q10: no post-lock edit while a live slip covers the GS');
select lives_ok(
  $$update public.transfer_slips set status = 'VOIDED', voided_at = now(),
           voided_by = 'aaaaaaaa-0000-4000-8000-0000000005e3', void_reason = 'edited after lock'
     where slip_no in ('PGTAP-TRF-DT', 'PGTAP-TRF-OP', 'PGTAP-TRF-DT2')$$,
  'DEC-65 / Q10: Management voids the slips');
select lives_ok(
  $$update public.goods_slips set status = 'PENDING_TRANSFER_SLIP' where gs_no = 'PGTAP-P5-A'$$,
  'DEC-65 / Q10: after the void the GS waits for a new slip');

select set_config('app.user_id', '', true);
select * from finish();
rollback;
